// Independent read-only inspection using the packaged application's own Node
// and SQLite binary. Supports published formats without importing product code.
import {execFileSync} from 'node:child_process';
import {join} from 'node:path';
export function readPackagedState(executable,resources,dir,env={}){
 const code=`const D=require(${JSON.stringify(join(resources,'service/node_modules/better-sqlite3'))});const d=new D(${JSON.stringify(join(dir,'data.sqlite'))},{readonly:true});const q=n=>'"'+n.replaceAll('"','""')+'"';const layout=JSON.parse(d.prepare("SELECT value FROM meta WHERE key='layout'").get().value);const version=Number(d.prepare("SELECT value FROM meta WHERE key='schema_version'").get().value);function model(){const h=d.prepare('SELECT body FROM wm_header WHERE id=1').get();if(!h)return undefined;return Object.fromEntries(JSON.parse(h.body).layout.map(([k,kind])=>[k,kind==='value'?JSON.parse(d.prepare('SELECT body FROM wm_values WHERE id=?').get(k).body):kind==='list'?d.prepare('SELECT body FROM '+q('wm_'+k)+' ORDER BY ord').all().map(r=>JSON.parse(r.body)):Object.fromEntries(d.prepare('SELECT id,body FROM '+q('wm_'+k)+' ORDER BY ord').all().map(r=>[r.id,JSON.parse(r.body)]))]));}const out=Object.fromEntries(layout.map(([k,rep])=>[k,rep==='map'?Object.fromEntries(d.prepare('SELECT id,body FROM '+q(k)+' ORDER BY ord').all().map(r=>[r.id,JSON.parse(r.body)])):rep==='list'?d.prepare('SELECT body FROM '+q(k)+' ORDER BY pos').all().map(r=>JSON.parse(r.body)):k==='workModel'&&version>=3?model()??JSON.parse(d.prepare('SELECT body FROM doc WHERE key=?').get(k).body):JSON.parse(d.prepare('SELECT body FROM doc WHERE key=?').get(k).body)]));console.log(JSON.stringify(out));d.close();`;
 return JSON.parse(execFileSync(executable,['-e',code],{env:{...process.env,...env,ELECTRON_RUN_AS_NODE:'1'},encoding:'utf8',maxBuffer:64*1024*1024}));
}
